package com.interviewiq.service;
import com.fasterxml.jackson.databind.*;import com.interviewiq.domain.*;import com.interviewiq.repository.*;import org.springframework.http.HttpStatus;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;import org.springframework.web.server.ResponseStatusException;import java.util.*;
@Service public class RoadmapService {
 private final RoadmapTaskRepository tasks;private final AssessmentRepository assessments;private final ObjectMapper json;
 public RoadmapService(RoadmapTaskRepository t,AssessmentRepository a,ObjectMapper j){tasks=t;assessments=a;json=j;}
 @Transactional public List<TaskView> get(AppUser user){var list=tasks.findByUserIdOrderByIdAsc(user.getId());if(list.isEmpty()){var latest=assessments.findByUserIdOrderByCreatedAtDesc(user.getId()).stream().filter(a->a.getResultJson()!=null).findFirst();List<String> focus=new ArrayList<>();if(latest.isPresent())try{JsonNode scores=json.readTree(latest.get().getResultJson()).path("skillScores");scores.fields().forEachRemaining(e->{if(e.getValue().asInt()<70)focus.add(e.getKey());});}catch(Exception ignored){}if(focus.isEmpty())focus.addAll(List.of("Spring Boot","SQL","Communication"));List<RoadmapTask> seeded=new ArrayList<>();for(int i=0;i<focus.size();i++){String topic=focus.get(i);String task=switch(topic.toLowerCase()){case "spring boot","spring data jpa","hibernate"->"Create a small entity and repository, then explain how persistence is wired.";case "sql"->"Write a query using a join and an aggregate, then explain its result.";case "react","javascript"->"Build a small component that manages state and handles an interaction.";case "communication"->"Prepare a concise Situation, Action, Result story from a project.";default->"Explain the key concepts in "+topic+" and apply them in a short example.";};seeded.add(new RoadmapTask(user,"Practice "+topic,topic,"This area is a priority based on your assessment and target role.",task,"30–45 min"));}list=tasks.saveAll(seeded);}
 return list.stream().map(this::view).toList();}
 @Transactional public TaskView update(AppUser user,Long id,String status){if(!Set.of("NOT_STARTED","IN_PROGRESS","COMPLETED").contains(status))throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"Invalid roadmap status.");RoadmapTask task=tasks.findById(id).filter(t->t.getUser().getId().equals(user.getId())).orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND,"Roadmap item not found."));task.setStatus(status);return view(tasks.save(task));}
 private TaskView view(RoadmapTask t){return new TaskView(t.getId(),t.getTitle(),t.getTopic(),t.getRationale(),t.getPracticeTask(),t.getStatus(),t.getEstimate());}
 public record TaskView(Long id,String title,String topic,String why,String task,String status,String estimate){}
}
